import{_ as o,o as p,c as d,a5 as t}from"./chunks/framework.DJo0M80U.js";const g=JSON.parse('{"title":"HJ71 字符串通配符","description":"中等 通过率：22.02% 时间限制：1秒 空间限制：32M 知识点 字符串 描述 问题描述：在计算机中，通配符一种特殊语法，广泛应用于文件搜索、数据库、正则表达式等领域。现要求各位实现字符串通配符的算法。 要求： 实现如下2个通配符： ：匹配0个或以上的字符（注：能被 和?匹配。","frontmatter":{"title":"HJ71 字符串通配符","date":"2026-08-11T00:00:00.000Z","categories":["前端面试与实战"],"tags":["前端面试","算法","求职","教程","OneNote","算法训练"],"description":"中等 通过率：22.02% 时间限制：1秒 空间限制：32M 知识点 字符串 描述 问题描述：在计算机中，通配符一种特殊语法，广泛应用于文件搜索、数据库、正则表达式等领域。现要求各位实现字符串通配符的算法。 要求： 实现如下2个通配符： ：匹配0个或以上的字符（注：能被 和?匹配。","sidebarWeight":109,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/a-吊打面试官/算法题/特定算法/HJ71 字符串通配符.md"},"headers":[],"relativePath":"posts/前端面试与实战/03-算法训练/特定算法/HJ71 字符串通配符.md","filePath":"posts/前端面试与实战/03-算法训练/特定算法/HJ71 字符串通配符.md"}'),c={name:"posts/前端面试与实战/03-算法训练/特定算法/HJ71 字符串通配符.md"};function r(s,e,i,n,a,l){return p(),d("div",null,[...e[0]||(e[0]=[t('<div><h1 id="hj71-字符串通配符" tabindex="-1">HJ71 字符串通配符 <a class="header-anchor" href="#hj71-字符串通配符" aria-label="Permalink to &quot;HJ71 字符串通配符&quot;">​</a></h1><blockquote><p>本节目标：理解“HJ71 字符串通配符”的核心思路，并能把它用于实际开发或面试表达。 中等 通过率：22.02% 时间限制：1秒 空间限制：32M 知识点==字符串== <strong>描述</strong> 问题描述：在计算机中，通配符一种特殊语法，广泛应用于文件搜索、数据库、正则表达式等领域。现要求各位实现字符串通配符的算法。 要求： 实现如下2个通配符： <em>：匹配0个或以上的字符（注：能被</em>和?匹配的字符仅由英文字母和数字0到9组成，下同） ？：匹配1个字符 注意：匹配时不区分大小写。 输入： 通配符表达式； 一组字符串。 输出： 返回不区分大小写的匹配结果，匹配成功输出true，匹配失败输出false 数据范围：字符串长度：1≤�≤100 1≤<em>s</em>≤100 进阶：时间复杂度：�(�2) <em>O</em>(_n_2) ，空间复杂度：�(�) <em>O</em>(<em>n</em>) <strong>输入描述：</strong> 先输入一个带有通配符的字符串，再输入一个需要匹配的字符串 <strong>输出描述：</strong> 返回不区分大小写的匹配结果，匹配成功输出true，匹配失败输出false <strong>示例1</strong> 输入： te?t*.<em>txt12.xls ==复制== 输出： false ==复制== <strong>示例2</strong> 输入： zzz ==复制== 输出： false ==复制== <strong>示例3</strong> 输入： pqpppq ==复制== 输出： false ==复制== <strong>示例4</strong> 输入： *<em>Z0QZz ==复制== 输出： true ==复制== <strong>示例5</strong> 输入： ?<em>Bc</em>?abcd ==复制== 输出： true ==复制== <strong>示例6</strong> 输入： h</em>?<em>ah#a ==复制== 输出： false ==复制== 说明： 根据题目描述可知能被</em>和?匹配的字符仅由英文字母和数字0到9组成，所以?不能匹配#，故输出false <strong>示例7</strong> 输入： p</em>p<em>qp**pq</em>p<strong>p</strong>*ppqpppppppqppqqppqppppqqqppqppqpqqqppqpqpppqpppqpqqqpqqp ==复制== 输出： false</p></blockquote><p>这个问题是关于实现一个简化版的通配符匹配算法，它需要处理两种通配符：<code>*</code> 和 <code>?</code>。<code>*</code> 可以匹配任意数量（包括零）的字符，而 <code>?</code> 匹配恰好一个字符。这里提供的匹配算法是大小写不敏感的。</p><p>由于算法的复杂性主要来自于 <code>*</code> 通配符的存在，因此一个高效的方法是使用动态规划来解决这个问题。我们可以创建一个布尔型的二维数组 <code>dp[i][j]</code>，其中 <code>dp[i][j]</code> 表示通配符模式的前 <code>i</code> 个字符和字符串的前 <code>j</code> 个字符是否匹配。</p><p>算法步骤如下：</p><ol><li>初始化 <code>dp[0][0]</code> 为 <code>true</code>，因为两个空字符串是匹配的。</li><li>对于模式 <code>p</code> 的第一个字符为 <code>*</code>，<code>dp[1][0]</code> 应为 <code>true</code>，因为 <code>*</code> 可以匹配空字符串。</li><li>遍历模式 <code>p</code> 和字符串 <code>s</code>，根据当前字符更新 <code>dp</code> 表：</li></ol><ul><li>如果 <code>p[i]</code> 是 <code>?</code> 或当前字符在 <code>p</code> 和 <code>s</code> 中匹配（考虑到大小写不敏感，需要转换为同一大小写进行比较），则 <code>dp[i][j] = dp[i-1][j-1]</code>。</li><li>如果 <code>p[i]</code> 是 <code>*</code>，则 <code>dp[i][j] = dp[i-1][j] || dp[i][j-1]</code>。这表示 <code>*</code> 要么匹配 <code>s</code> 中的当前字符（<code>dp[i][j-1]</code>），要么不匹配任何字符（<code>dp[i-1][j]</code>）。</li></ul><ol start="4"><li>最终的匹配结果是 <code>dp[p.length][s.length]</code>。</li></ol><p>下面是实现这个算法的 Python 代码示例：</p><p>def isMatch(s, p): s, p = s.lower(), p.lower() # 转换为小写以进行大小写不敏感的比较 dp = [[False] * (len(s) + 1) for _ in range(len(p) + 1)] dp[0][0] = True for i in range(1, len(p) + 1): if p[i-1] == &#39;<em>&#39;: dp[i][0] = dp[i-1][0] else: break def isAlphanumeric(c): return c.isalnum() # 检查c是否为英文字母或数字 for i in range(1, len(p) + 1): for j in range(1, len(s) + 1): if p[i-1] == &#39;</em>&#39;: dp[i][j] = dp[i-1][j] or dp[i][j-1] elif p[i-1] == &#39;?&#39; and isAlphanumeric(s[j-1]): dp[i][j] = dp[i-1][j-1] elif p[i-1] == s[j-1]: dp[i][j] = dp[i-1][j-1] return dp[len(p)][len(s)]</p><p>while True: try: pattern = input() string = input() print(str(isMatch(string, pattern)).lower()) except EOFError: break</p><p>这段代码首先处理了一些边界条件，比如两个空字符串的匹配以及模式字符串以一个或多个 <code>*</code> 开头的情况。然后，它通过双重循环遍历字符串和模式，使用动态规划的方法填充 <code>dp</code> 表，最后根据 <code>dp</code> 表的最后一个元素返回匹配结果。</p></div>',1)])])}const _=o(c,[["render",r]]);export{g as __pageData,_ as default};
